function contentToDraft(rows, nowIso, daysAhead) {
  const now = Date.parse(nowIso);
  return rows.filter((r) => {
    const at = Date.parse(r.publish_at);
    return String(r.status).toLowerCase() === "idea" && r.topic && Number.isFinite(at) && at >= now - 86400000 && at <= now + daysAhead * 86400000;
  });
}

function buildCaptionRequest(row, s) {
  const system = [
    `You are the social media writer for ${s.businessName}. ${s.businessDescription}`,
    `Brand voice: ${s.brandVoice}. Language: ${s.language}.`,
    "Write one post per network for the topic. Instagram: hook first line, up to 150 words, line breaks. Facebook: up to 100 words.",
    "LinkedIn: professional, up to 150 words. X: under 260 characters. No made-up facts, prices or statistics.",
    "image_prompt: a description of one eye-catching image for the post (subject, setting, style, colours), with no text, logos or real people's faces in it.",
    'Answer with JSON only: {"instagram":"...","facebook":"...","linkedin":"...","x":"...","hashtags":"#tag1 #tag2 ...","image_prompt":"..."}',
  ].join("\n");
  const user = JSON.stringify({ topic: row.topic, notes: row.notes || "", call_to_action: row.call_to_action || s.defaultCallToAction });
  return {
    model: s.openAiModel,
    temperature: 0.7,
    response_format: { type: "json_object" },
    messages: [{ role: "system", content: system }, { role: "user", content: user }],
  };
}

const s = $('Settings').first().json;
const input = $input.all();
const index = new Map(input.map((it, i) => [it.json, i]));
const rows = input.map((i) => i.json).filter((r) => r.post_id);
return contentToDraft(rows, new Date().toISOString(), Number(s.daysAhead)).map((row) => ({ json: { ...row, request: buildCaptionRequest(row, s) }, pairedItem: { item: index.get(row) } }));

function readAiJson(response) {
  const content = response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
  if (!content) throw new Error("OpenAI returned no answer: " + JSON.stringify(response).slice(0, 300));
  try {
    return JSON.parse(content);
  } catch {
    throw new Error("OpenAI answer was not valid JSON: " + content.slice(0, 300));
  }
}

const rows = $('Posts to write').all();
return $input.all().map((item, i) => {
  const row = rows[i].json;
  const ai = readAiJson(item.json);
  return { json: { post_id: row.post_id, status: 'waiting approval', instagram: ai.instagram || '', facebook: ai.facebook || '',
    linkedin: ai.linkedin || '', x: ai.x || '', hashtags: ai.hashtags || '', image_prompt: ai.image_prompt || '', image_url: row.image_url || '',
    topic: row.topic, publish_at: row.publish_at }, pairedItem: { item: i } };
});

function buildImageRequest(row, s) {
  const prompt = `${row.image_prompt || row.topic}. Style: ${s.imageStyle}. No text, no logos, no watermarks.`.slice(0, 3800);
  const body = { model: s.imageModel, prompt, n: 1, size: "1024x1024" };
  if (!/^gpt-image/.test(String(s.imageModel))) body.response_format = "b64_json";
  return body;
}

return { json: { ...$json, request: buildImageRequest($json, $('Settings').first().json) } };

const draft = $('Image request').item.json;
const b64 = $json.data && $json.data[0] && $json.data[0].b64_json;
if (!b64) return { json: { ...draft, image_error: ($json.error && ($json.error.message || $json.error)) || 'no image returned' } };
const data = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), draft.post_id + '.png', 'image/png');
return { json: draft, binary: { data } };

const draft = $('Image file').item.json;
const url = ($json.images && $json.images[0] && $json.images[0].source) || '';
const { image_error, ...row } = draft;
return { json: { ...row, image_url: url, image_note: url ? 'AI image' : 'Image not created: ' + (image_error || ($json.error && ($json.error.message || $json.error)) || 'upload failed') } };

const posts = $('All drafts').all().map((i) => i.json);
const list = posts.map((p) => '- ' + p.publish_at + ': ' + p.topic + (p.image_url ? ' (image: ' + p.image_url + ')' : p.image_note ? ' (' + p.image_note + ')' : '')).join('\n');
return [{ json: { count: posts.length, list }, pairedItem: $input.all().map((_, i) => ({ item: i })) }];

