function duePosts(rows, nowIso, status = "approved") {
  const now = Date.parse(nowIso);
  return rows.filter((r) => String(r.status).toLowerCase() === status && Date.parse(r.publish_at) <= now);
}

const input = $input.all();
const index = new Map(input.map((it, i) => [it.json, i]));
const rows = input.map((i) => i.json).filter((r) => r.post_id);
// One post per run (the trigger runs hourly), so each result clearly belongs to one post.
return duePosts(rows, new Date().toISOString(), "approved").slice(0, 1).map((row) => ({ json: row, pairedItem: { item: index.get(row) } }));

function publishOutcome(results) {
  const failed = results.filter((r) => r.enabled && r.error).map((r) => `${r.network}: ${r.error}`);
  const done = results.filter((r) => r.enabled && !r.error).map((r) => r.network);
  return {
    status: failed.length === 0 ? "published" : done.length ? "partly published" : "failed",
    published_to: done.join(", "),
    errors: failed.join(" | ").slice(0, 1000),
  };
}

// Each network node sends failures to its error output. A disabled node passes its input through unchanged,
// so a network only counts as published when its node returned a new response without an error.
const post = $('Posts due now').first();
const steps = [
  ['facebook', 'Post to Facebook'], ['instagram', 'Instagram: upload image'], ['instagram', 'Instagram: publish'],
  ['linkedin', 'Post to LinkedIn'], ['x', 'Post to X'],
];
const emitted = (node) => {
  try { if (!$(node).isExecuted) return null; } catch { return null; }
  let failed = [];
  try { failed = $(node).all(1); } catch { failed = []; }
  if (failed.length) return { json: failed[0].json, failed: true };
  const ok = $(node).all(0);
  return ok.length ? { json: ok[0].json, failed: false } : null;
};
const status = {};
let previous = JSON.stringify(post.json);
for (const [network, node] of steps) {
  const out = emitted(node);
  if (!out) { status[network] = status[network] || { network, enabled: false }; continue; }
  const now = JSON.stringify(out.json);
  const passedThrough = !out.failed && now === previous;
  previous = now;
  if (status[network] && status[network].error) continue;
  if (passedThrough) { status[network] = status[network] || { network, enabled: false }; continue; }
  const e = out.json.error;
  const message = out.failed ? (e && (e.message || e.description || e)) || 'failed' : out.json.statusCode ? out.json.message || 'HTTP ' + out.json.statusCode : '';
  status[network] = { network, enabled: true, error: message ? String(message).slice(0, 200) : '' };
}
return [{ json: { post_id: post.json.post_id, ...publishOutcome(Object.values(status)), published_at: new Date().toISOString() }, pairedItem: { item: 0 } }];

function parseMetaEvents(body, pageId, igId) {
  const out = [];
  const own = (id) => id && (String(id) === String(pageId) || String(id) === String(igId));
  const ig = body && body.object === "instagram";
  for (const entry of (body && body.entry) || []) {
    for (const ch of entry.changes || []) {
      const v = ch.value || {};
      if (!ig && ch.field === "feed" && v.item === "comment" && v.verb === "add" && v.message && !own(v.from && v.from.id)) {
        out.push({ channel: "facebook_comment", target_id: v.comment_id, text: v.message, author: (v.from && v.from.name) || "", post_id: v.post_id || "" });
      }
      if (ig && ch.field === "comments" && v.text && !own(v.from && v.from.id)) {
        out.push({ channel: "instagram_comment", target_id: v.id, text: v.text, author: (v.from && v.from.username) || "", post_id: (v.media && v.media.id) || "" });
      }
    }
    for (const m of entry.messaging || []) {
      if (!m.message || !m.message.text || m.message.is_echo || own(m.sender && m.sender.id)) continue;
      out.push({ channel: ig ? "instagram_dm" : "messenger", target_id: m.sender.id, text: m.message.text, author: "", post_id: "" });
    }
  }
  return out.map((e) => ({ ...e, text: String(e.text).slice(0, 2000) }));
}

function buildSocialReplyRequest(event, s) {
  const isPrivate = /dm|messenger/.test(event.channel);
  const system = [
    `You answer ${isPrivate ? "private messages" : "public comments"} for ${s.businessName}. ${s.businessDescription}`,
    `Brand voice: ${s.brandVoice}. Reply in the person's language. Keep it short: 1 to 3 sentences.`,
    `What you know (use only this, never invent prices, dates or promises): ${s.replyKnowledge}`,
    "needs_human = true for complaints, refunds, order problems, angry or abusive messages, legal or personal-data requests, or anything you cannot answer from what you know.",
    "category: question, praise, complaint, spam, other. For spam, reply with an empty string.",
    'Answer with JSON only: {"reply":"...","needs_human":false,"category":"question","sentiment":"positive|neutral|negative"}',
  ].join("\n");
  return {
    model: s.openAiModel, temperature: 0.4, response_format: { type: "json_object" },
    messages: [{ role: "system", content: system }, { role: "user", content: JSON.stringify({ channel: event.channel, from: event.author, text: event.text }) }],
  };
}

const s = $('Settings').first().json;
return parseMetaEvents($('Meta events').first().json.body, s.facebookPageId, s.instagramAccountId)
  .map((e) => ({ json: { ...e, received_at: new Date().toISOString(), request: buildSocialReplyRequest(e, s) }, pairedItem: { item: 0 } }));

function readAiJson(response) {
  const content = response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
  if (!content) throw new Error("OpenAI returned no answer: " + JSON.stringify(response).slice(0, 300));
  try {
    return JSON.parse(content);
  } catch {
    throw new Error("OpenAI answer was not valid JSON: " + content.slice(0, 300));
  }
}

const s = $('Settings').first().json;
const src = $('Comments and messages').all();
return $input.all().map((item, i) => {
  const e = src[i].json;
  let a;
  try { a = readAiJson(item.json); } catch { a = { reply: '', needs_human: true, category: 'other', sentiment: '' }; }
  const spam = a.category === 'spam';
  const human = !spam && (a.needs_human === true || !a.reply);
  const send = !spam && !human && s.autoReply === true;
  return { json: { received_at: e.received_at, channel: e.channel, target_id: e.target_id, author: e.author, post_id: e.post_id, text: e.text,
    category: a.category || '', sentiment: a.sentiment || '', reply: spam ? '' : (a.reply || ''),
    status: spam ? 'ignored (spam)' : send ? 'replied automatically' : 'sent to you for review', send, human: !spam && !send }, pairedItem: { item: i } };
});

